//! Animal feeders and their food (`feeding.tsv`, generated by
//! `research/scripts/feeding.py`): a placed feeder is known by its building item
//! (`ecs::UsedItem`), takes the food named for its animal, and the Farmer makes that food
//! in his workshop (crafted at once, no station), from the recipes kept here in the format
//! of `recipes.tsv`.

use std::collections::HashMap;
use std::sync::OnceLock;

use crate::recipes::{Recipe, Table};

const TABLE: &str = include_str!("../feeding.tsv");

pub struct Feeding {
    /// the food recipes and the categories they take
    pub table: Table,
    /// feeder item -> food item
    pub feeders: HashMap<u32, u32>,
}

impl Feeding {
    pub fn parse(text: &str) -> Feeding {
        let feeders = text
            .lines()
            .filter_map(|line| {
                let f: Vec<&str> = line.split('\t').collect();
                (f.first() == Some(&"feeder") && f.len() >= 3).then(|| Some((f[1].parse().ok()?, f[2].parse().ok()?))).flatten()
            })
            .collect();
        Feeding { table: Table::parse(text), feeders }
    }

    /// The food a feeder (by its building item) takes.
    pub fn food_of(&self, feeder_item: u32) -> Option<u32> {
        self.feeders.get(&feeder_item).copied()
    }

    /// The recipe that makes a food.
    pub fn recipe(&self, food: u32) -> Option<&Recipe> {
        self.table.recipes.iter().find(|r| r.makes(food) > 0)
    }
}

pub fn data() -> &'static Feeding {
    static DATA: OnceLock<Feeding> = OnceLock::new();
    DATA.get_or_init(|| Feeding::parse(TABLE))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_goat_feeder_takes_goat_food_the_farmer_makes() {
        let goat_feeder = 761665893;
        let food = data().food_of(goat_feeder).unwrap();
        assert_eq!(crate::names::item(food), "Goat Feeding");
        assert_eq!(data().recipe(food).unwrap().makes(food), 50);
        assert_eq!(data().feeders.len(), 9);
    }
}
